solutions.naive:
class Solution:
    def isCovered(self, ranges: list[list[int]], left: int, right: int) -> bool:
        for x in range(left, right + 1):
            found = False
            for start, end in ranges:
                if start <= x <= end:
                    found = True
                    break
            if not found:
                return False
        return True

solutions.better:
class Solution:
    def isCovered(self, ranges: list[list[int]], left: int, right: int) -> bool:
        need = left
        for start, end in sorted(ranges):
            if end < need:
                continue
            if start > need:
                return False
            need = max(need, end + 1)
            if need > right:
                return True
        return False

